import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import { useCart } from "react-use-cart";
import products from "../products/Products";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import { Link } from "react-router-dom";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */

const CATEGORIES = [
  { id: "All", label: "All", icon: Sparkles },
  { id: "Rings", label: "Rings", icon: Gem },
  { id: "Necklaces", label: "Necklaces", icon: Sparkles },
  { id: "Bracelets", label: "Bracelets", icon: CircleDot },
  { id: "Earrings", label: "Earrings", icon: Star },
  { id: "Chains", label: "Chains", icon: Link2 },
  { id: "Watches", label: "Watches", icon: Watch },
];

const CATEGORY_ICON = {
  Rings: Gem,
  Necklaces: Sparkles,
  Bracelets: CircleDot,
  Earrings: Star,
  Chains: Link2,
  Watches: Watch,
};

/* ============================================================
   PRODUCTS
   ============================================================ */

const PRODUCTS = products.map((p) => ({
  id: p.id,
  name: p.title,
  category: p.category,
  price: Number(p.price) || 0,
  icon: CATEGORY_ICON[p.category] || Sparkles,
  badge: p.badge,
  image: p.thumbnail,
}));

/* ============================================================
   FOOTER
   ============================================================ */

function PlaceholderFooter() {
  return (
    <footer className="lux-footer">
      <div className="lux-footer-inner">

        <div className="lux-footer-col lux-footer-brand">
          <div className="lux-logo lux-logo-footer">
            MAISON&nbsp;&amp;&nbsp;LUXE
          </div>

          <p>
            Fine accessories, crafted with intention.
            Timeless pieces for every story.
          </p>

          <div className="lux-footer-social">
            <a href="#" aria-label="Instagram">
              <FaInstagram size={16} />
            </a>

            <a href="#" aria-label="Facebook">
              <FaFacebookF size={16} />
            </a>

            <a href="#" aria-label="Twitter">
              <FaTwitter size={16} />
            </a>
          </div>
        </div>

        <div className="lux-footer-col">
          <h4>Shop</h4>
          <a href="#">Rings</a>
          <a href="#">Necklaces</a>
          <a href="#">Watches</a>
        </div>

        <div className="lux-footer-col">
          <h4>Support</h4>
          <a href="#">Shipping</a>
          <a href="#">Returns</a>
          <a href="#">Contact Us</a>
        </div>

        <div className="lux-footer-col">
          <h4>Newsletter</h4>

          <p>
            Be first to know about new arrivals.
          </p>

          <div className="lux-footer-form">
            <input
              type="email"
              placeholder="Your email"
            />

            <button type="button">
              Join
            </button>
          </div>
        </div>

      </div>

      <div className="lux-footer-bottom">
        © {new Date().getFullYear()} Maison &amp; Luxe.
        All rights reserved.
      </div>
    </footer>
  );
}

/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {
  const { addItem } = useCart();

  const Icon = product.icon;

  const [imgFailed, setImgFailed] = useState(false);

  const showImage = product.image && !imgFailed;

  const handleAddToCart = () => {
    addItem({
      id: product.id,
      title: product.name,
      price: product.price,
      images: product.image ? [product.image] : [],
    });

    alert("Product added to cart successfully!");
  };

  return (
    <article className="lux-card">

      <div className="lux-card-media"/>

        {showImage ? (
          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-image-link"
          >
            <img
              src={product.image}
              alt={product.name}
              className="lux-card-img"
              loading="lazy"
              onError={() => setImgFailed(true)}
            />
          </Link>
        ) : (
          <Link
            to={`/AllSingleProduct/${product.id}`}
            className="lux-card-media-icon"
          >
            <Icon
              size={40}
              strokeWidth={1}
            />
          </Link>
          
        )};

 return (
    <div className="lux-root">
      <style>{`
       ${fontImport}

  .lux-root {

    --bg: #1B1714;

    --bg-alt: #15110F;

    --surface: #211C18;

    --surface-hover: #2A241F;

    --border: rgba(201, 166, 107, 0.18);

    --border-strong: rgba(201, 166, 107, 0.35);

    --gold: #C9A66B;

    --gold-light: #E2C994;

    --gold-dim: #A88A5A;

    --ivory: #F5EFE6;

    --muted: #A9A09A;

    --wine: #4A2630;

    background: var(--bg);

    background-image:

      radial-gradient(

        ellipse 60% 40% at 15% 0%,

        rgba(201, 166, 107, 0.06),

        transparent 60%

      ),

      radial-gradient(

        ellipse 50% 35% at 100% 20%,

        rgba(201, 166, 107, 0.05),

        transparent 60%

      );

    color: var(--ivory);

    font-family: "Jost", sans-serif;

    min-height: 100vh;

    -webkit-font-smoothing: antialiased;

  }

  .lux-root *,

  .lux-root *::before,

  .lux-root *::after {

    box-sizing: border-box;

  }

  /* =========================

     NAVBAR

  ========================= */

  .lux-navbar {

    border-bottom: 1px solid var(--border);

    background: rgba(27, 23, 20, 0.9);

    position: sticky;

    top: 0;

    z-index: 20;

    backdrop-filter: blur(6px);

  }

  .lux-navbar-inner {

    max-width: 1240px;

    margin: 0 auto;

    padding: 18px 24px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 16px;

  }

  .lux-navbar-menu {

    display: none;

  }

  .lux-logo {

    font-family: "Cormorant Garamond", serif;

    font-size: 22px;

    letter-spacing: 0.14em;

    color: var(--gold-light);

    font-weight: 500;

    white-space: nowrap;

  }

  .lux-navbar-links {

    display: flex;

    gap: 34px;

  }

  .lux-navbar-links a {

    color: var(--muted);

    text-decoration: none;

    font-size: 13px;

    letter-spacing: 0.08em;

    text-transform: uppercase;

    padding-bottom: 4px;

    border-bottom: 1px solid transparent;

    transition:

      color 0.2s ease,

      border-color 0.2s ease;

  }

  .lux-navbar-links a:hover,

  .lux-navbar-links a.active {

    color: var(--gold-light);

    border-color: var(--gold);

  }

  .lux-navbar-actions {

    display: flex;

    gap: 6px;

  }

  .lux-icon-btn {

    background: transparent;

    border: none;

    color: var(--ivory);

    padding: 8px;

    border-radius: 999px;

    cursor: pointer;

    display: flex;

    align-items: center;

    justify-content: center;

    transition:

      background 0.2s ease,

      color 0.2s ease;

  }

  .lux-icon-btn:hover {

    background: var(--surface-hover);

    color: var(--gold-light);

  }

  /* =========================

     HERO

  ========================= */

  .lux-hero {

    max-width: 1240px;

    margin: 0 auto;

    padding: 72px 24px 40px;

    text-align: center;

  }

  .lux-hero-eyebrow {

    font-size: 12px;

    letter-spacing: 0.32em;

    text-transform: uppercase;

    color: var(--gold-dim);

    margin-bottom: 14px;

  }

  .lux-hero h1 {

    font-family: "Cormorant Garamond", serif;

    font-weight: 500;

    font-size: clamp(36px, 6vw, 58px);

    letter-spacing: 0.02em;

    margin: 0;

    color: var(--ivory);

  }

  .lux-hero-divider {

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 14px;

    margin: 22px auto 0;

    width: 220px;

  }

  .lux-hero-divider .line {

    height: 1px;

    flex: 1;

    background: linear-gradient(

      90deg,

      transparent,

      var(--gold),

      transparent

    );

  }

  .lux-hero-divider .diamond {

    width: 7px;

    height: 7px;

    background: var(--gold);

    transform: rotate(45deg);

    flex-shrink: 0;

  }

  .lux-hero p {

    margin: 22px auto 0;

    max-width: 480px;

    color: var(--muted);

    font-weight: 300;

    font-size: 15px;

    line-height: 1.7;

  }

  /* =========================

     CATEGORY FILTERS

  ========================= */

  .lux-filters {

    max-width: 1240px;

    margin: 0 auto;

    padding: 0 24px 56px;

    display: flex;

    flex-wrap: wrap;

    justify-content: center;

    gap: 12px;

  }

  .lux-filter-btn {

    display: flex;

    align-items: center;

    gap: 8px;

    padding: 10px 20px;

    border-radius: 999px;

    border: 1px solid var(--border);

    background: var(--surface);

    color: var(--muted);

    font-family: "Jost", sans-serif;

    font-size: 13px;

    letter-spacing: 0.06em;

    text-transform: uppercase;

    cursor: pointer;

    transition: all 0.25s ease;

  }

  .lux-filter-btn:hover {

    border-color: var(--border-strong);

    color: var(--gold-light);

    background: var(--surface-hover);

  }

  .lux-filter-btn.is-active {

    background: linear-gradient(

      135deg,

      var(--gold),

      #A9865A

    );

    border-color: var(--gold);

    color: #211B17;

    font-weight: 500;

  }

  .lux-filter-btn.is-active svg {

    color: #211B17;

  }

  /* =========================

     PRODUCT GRID

  ========================= */

  .lux-grid-section {

    max-width: 1240px;

    margin: 0 auto;

    padding: 0 24px 100px;

  }

  .lux-grid-meta {

    display: flex;

    justify-content: space-between;

    align-items: baseline;

    margin-bottom: 24px;

    color: var(--muted);

    font-size: 13px;

    letter-spacing: 0.04em;

  }

  .lux-grid-meta strong {

    color: var(--gold-light);

    font-weight: 500;

  }

  .lux-grid {

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 26px;

  }

  /* =========================

     PRODUCT CARD

  ========================= */

  .lux-card {

    background: var(--surface);

    border: 1px solid var(--border);

    border-radius: 4px;

    overflow: hidden;

    display: flex;

    flex-direction: column;

    transition:

      transform 0.3s ease,

      border-color 0.3s ease,

      box-shadow 0.3s ease;

  }

  .lux-card:hover {

    transform: translateY(-4px);

    border-color: var(--border-strong);

    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);

  }

  .lux-card-media {

    position: relative;

    aspect-ratio: 1 / 1;

    background:

      radial-gradient(

        circle at 30% 20%,

        rgba(201, 166, 107, 0.14),

        transparent 55%

      ),

      linear-gradient(

        160deg,

        var(--bg-alt),

        #1a1512

      );

    display: flex;

    align-items: center;

    justify-content: center;

    overflow: hidden;

  }

  .lux-card-img {

    width: 100%;

    height: 100%;

    object-fit: cover;

    object-position: center;

    display: block;

    transition: transform 0.5s ease;

  }

  .lux-card:hover .lux-card-img {

    transform: scale(1.06);

  }

  .lux-card-media-icon {

    color: var(--gold-dim);

  }

  .lux-card:hover .lux-card-media-icon {

    color: var(--gold-light);

  }

  .lux-card-badge {

    position: absolute;

    top: 12px;

